import scrapy
import os

class scrapysettings(scrapy.settings.Settings):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.settings.copy_over("USER_AGENT", "Scrapy crawler")

def start_requests():
    returned = []

    for path in os.listdir:
        if path.endswith('.html'):
            req = scrapy.Request(url=path, callback=fetch_page_latest, meta={'path': path})
            returned.append(req)

    return returned

def fetch_page_latest(url):
    page = url

    # this is the path to the page
    current_dir = os.getcwd()

    filename = page.split('/')[1]

    file_path = os.path.join(current_dir, filename)

    try:
        with open(file_path, 'w') as f:
            f.write(page)

        return filename
    except:
        pass

